<?php require_once __DIR__.'/config/security.php'; require_permission('backup.manage'); $page_title='Backup & Restore'; $backups=$pdo->query('SELECT b.*,u.name FROM backups b LEFT JOIN users u ON u.id=b.created_by ORDER BY b.created_at DESC')->fetchAll(); include __DIR__.'/partials/header.php'; ?>
<div class="hero compact"><div><div class="eyebrow">RECOVERY CENTER</div><h1>Backup & restore</h1><p>Database backup, restore and recovery workflow. Use only with authorized administrator access.</p></div><button class="btn primary" onclick="createBackup()">⇩ Create Backup</button></div>
<div class="panel"><div class="panel-head"><div><h3>Recovery safeguards</h3><p>Always create a backup before importing a restore file.</p></div></div><div class="backup-note">The system creates SQL dumps using the server's <code>mysqldump</code> utility. Restore imports an SQL file into the configured campus database. For production, store backups outside the web root and encrypt them.</div><form id="restoreForm" style="padding:20px"><input type="file" name="sql_file" accept=".sql" required><button class="btn danger">Restore SQL Backup</button></form></div>
<div class="panel"><div class="panel-head"><h3>Backup history</h3></div><div class="table-wrap"><table><thead><tr><th>File</th><th>Created By</th><th>Size</th><th>Date</th><th>Download</th></tr></thead><tbody><?php foreach($backups as $b):?><tr><td><?=e($b['filename'])?></td><td><?=e($b['name']??'System')?></td><td><?=number_format(((int)$b['size_bytes'])/1024,1)?> KB</td><td><?=e($b['created_at'])?></td><td><a class="btn ghost" href="api/backup.php?id=<?=$b['id']?>">Download</a></td></tr><?php endforeach;?></tbody></table></div></div>
<script>async function createBackup(){try{let r=await fetch('api/backup.php',{method:'POST'});let j=await r.json();if(!j.ok)throw Error(j.message);alert('Backup created: '+j.filename);location.reload()}catch(e){alert(e.message)}}document.querySelector('#restoreForm').addEventListener('submit',async e=>{e.preventDefault();if(!confirm('Restore this database backup? Create a backup first.'))return;let f=new FormData(e.target);f.append('action','restore');let r=await fetch('api/backup.php',{method:'POST',body:f});let j=await r.json();alert(j.message);if(j.ok)location.reload()})</script>
<?php include __DIR__.'/partials/footer.php'; ?>
